const input = $json || {};

const discord = Array.isArray(input.discord_messages)
  ? input.discord_messages
  : [];

const slack = Array.isArray(input.slack_messages)
  ? input.slack_messages
  : [];

const messages = [];

for (const msg of discord) {
  messages.push({
    platform: 'discord',
    message_id: msg.id || msg.message_id || null,
    author: msg.author?.username || msg.author || msg.user || 'Unknown',
    channel: msg.channel?.name || msg.channel || null,
    content: String(msg.content || msg.text || '').trim(),
    timestamp: msg.timestamp || msg.created_at || null
  });
}

for (const msg of slack) {
  messages.push({
    platform: 'slack',
    message_id: msg.ts || msg.id || msg.message_id || null,
    author: msg.user_name || msg.username || msg.user || 'Unknown',
    channel: msg.channel_name || msg.channel || null,
    content: String(msg.text || msg.content || '').trim(),
    timestamp: msg.ts || msg.timestamp || msg.created_at || null
  });
}

return [
  {
    json: {
      status: 'chat_messages_normalized',
      message_count: messages.length,
      messages
    }
  }
];

const data = $json || {};
const messages = data.messages || [];

const evidence = [];
const decisions = [];
const tasks = [];
const problems = [];
const dependencies = [];

function add(type, message) {
  evidence.push({
    evidence_id: `chat-${evidence.length + 1}`,
    type,
    content: message.content,
    author: message.author,
    platform: message.platform,
    channel: message.channel,
    timestamp: message.timestamp,
    message_id: message.message_id
  });
}

for (const message of messages) {
  const text = String(message.content || '').trim();
  const lower = text.toLowerCase();

  if (!text) continue;

  if (/\b(decided|decision|we will use|let's use|lets use|agreed|agreement|chosen|choose)\b/i.test(text)) {
    add('decision', message);
    decisions.push(text);
    continue;
  }

  if (/\b(todo|task|need to|needs to|implement|build|fix|finish|working on|assigned)\b/i.test(text)) {
    add('task', message);
    tasks.push(text);
    continue;
  }

  if (/\b(blocked|blocker|problem|issue|bug|broken|error|failure|failing|risk)\b/i.test(text)) {
    add('problem', message);
    problems.push(text);
    continue;
  }

  if (/\b(dependency|depends on|requires|using|connected to|integrated with)\b/i.test(text)) {
    add('dependency', message);
    dependencies.push(text);
    continue;
  }

  if (/\b(fixed|resolved|solved|implemented|deployed|completed|working now)\b/i.test(text)) {
    add('solution', message);
    continue;
  }
}

function unique(values) {
  return [...new Set(values.map(x => String(x).trim()).filter(Boolean))];
}

return [
  {
    json: {
      status: 'chat_evidence_extracted',
      message_count: messages.length,
      evidence_count: evidence.length,
      evidence,
      decisions: unique(decisions),
      tasks: unique(tasks),
      problems: unique(problems),
      dependencies: unique(dependencies),
      summary: {
        discord_messages: messages.filter(x => x.platform === 'discord').length,
        slack_messages: messages.filter(x => x.platform === 'slack').length,
        evidence: evidence.length,
        decisions: unique(decisions).length,
        tasks: unique(tasks).length,
        problems: unique(problems).length,
        dependencies: unique(dependencies).length
      }
    }
  }
];

const data = $json || {};

return [
  {
    json: {
      status: 'chat_context_ready',
      source: 'Discord + Slack',
      messages_processed: data.message_count || 0,
      chat_context: {
        evidence: data.evidence || [],
        decisions: data.decisions || [],
        tasks: data.tasks || [],
        problems: data.problems || [],
        dependencies: data.dependencies || []
      },
      summary: data.summary || {}
    }
  }
];
